import java.util.*;class Solution{public List<List<Integer>> kSmallestPairs(int[]a,int[]b,int k){List<List<Integer>>o=new ArrayList<>();if(a.length==0||b.length==0)return o;PriorityQueue<int[]>q=new PriorityQueue<>((x,y)->Long.compare((long)a[x[0]]+b[x[1]],(long)a[y[0]]+b[y[1]]));for(int i=0;i<a.length&&i<k;i++)q.add(new int[]{i,0});while(k-->0&&!q.isEmpty()){int[]x=q.remove();o.add(Arrays.asList(a[x[0]],b[x[1]]));if(++x[1]<b.length)q.add(x);}return o;}}
